//! wasm-bindgen API of the editor engine (`editor/src/engine-pkg`, generated by wasm-bindgen).

use goat_assets::AssetIo;
use goat_gfx_wgpu::{DisplayLayout, WgpuBackend};
use wasm_bindgen::prelude::*;

use crate::core::ViewPass;
use crate::core::{entity_of, id_of, EditorCore, TransformEdit};
use crate::tools::GizmoMode;

/// Engine log lines waiting for the editor's Console (`take_logs`).
static LOGS: std::sync::Mutex<Vec<(&'static str, String)>> = std::sync::Mutex::new(Vec::new());

fn log_sink(level: goat_core::log::Level, args: &std::fmt::Arguments<'_>) {
    let text = args.to_string();
    web_sys::console::log_1(&JsValue::from_str(&format!("[{}] {}", level.label(), text)));
    let level = match level {
        goat_core::log::Level::Error => "error",
        goat_core::log::Level::Warn => "warn",
        _ => "info",
    };
    if let Ok(mut l) = LOGS.lock() {
        if l.len() < 1000 {
            l.push((level, text));
        }
    }
}

#[wasm_bindgen]
pub struct EditorEngine {
    gfx: WgpuBackend,
    core: EditorCore,
    width: u32,
    height: u32,
    /// The Game view shows the 3DS's two screens (else the window).
    dual: bool,
    /// The Game view's own canvas (surface id): Scene and Game views drawn independently.
    game_surface: Option<usize>,
    scene_visible: bool,
    game_visible: bool,
}

#[wasm_bindgen]
impl EditorEngine {
    /// Starts the engine on a canvas (WebGPU, or WebGL2 when unavailable).
    pub async fn create(canvas: web_sys::HtmlCanvasElement) -> Result<EditorEngine, JsValue> {
        console_error_panic_hook::set_once();
        goat_core::log::set_sink(log_sink);
        goat_runtime::profiler::set_clock(|| web_sys::window().and_then(|w| w.performance()).map_or(0.0, |p| p.now() / 1000.0));
        let (w, h) = (canvas.width().max(1), canvas.height().max(1));
        let gfx = WgpuBackend::new_async(wgpu::SurfaceTarget::Canvas(canvas), w, h, DisplayLayout::Window).await.map_err(|e| JsValue::from_str(&e.to_string()))?;
        let mut core = EditorCore::new(AssetIo::new("assets"));
        core.aspect = w as f32 / h as f32;
        let mut me = EditorEngine { gfx, core, width: w, height: h, dual: false, game_surface: None, scene_visible: true, game_visible: false };
        me.core.first_frame(&mut me.gfx);
        Ok(me)
    }

    /// Engine log lines since the last call: `[[level, text], ...]` (JSON).
    pub fn take_logs(&self) -> String {
        let lines = LOGS.lock().map(|mut l| std::mem::take(&mut *l)).unwrap_or_default();
        serde_json::to_string(&lines).unwrap_or_else(|_| "[]".into())
    }

    pub fn backend_name(&self) -> String {
        goat_gfx::GraphicsBackend::name(&self.gfx).to_string()
    }

    /// Makes a project file available to the engine (the UI reads files through Tauri).
    pub fn put_file(&mut self, key: &str, bytes: Vec<u8>) {
        // the UI re-sends every file (syncFiles): only real changes reload things
        let same = self.core.io.read(key).is_ok_and(|old| old == bytes);
        self.core.io.put(key, bytes);
        if !same {
            self.core.file_changed(&mut self.gfx, key);
        }
    }

    /// The Scene view's canvas was resized.
    pub fn resize(&mut self, width: u32, height: u32) {
        self.width = width.max(1);
        self.height = height.max(1);
        self.gfx.use_surface(0);
        self.gfx.resize(self.width, self.height);
        self.core.aspect = self.width as f32 / self.height as f32;
    }

    /// The Game view's own canvas (Unity: Scene and Game views are separate and can show side by
    /// side). Without it the one canvas shows whichever view `set_scene_view` picks.
    pub fn attach_game_canvas(&mut self, canvas: web_sys::HtmlCanvasElement) -> Result<(), JsValue> {
        let (w, h) = (canvas.width().max(1), canvas.height().max(1));
        let id = self.gfx.add_surface(wgpu::SurfaceTarget::Canvas(canvas), w, h, DisplayLayout::Window).map_err(|e| JsValue::from_str(&e.to_string()))?;
        self.gfx.use_surface(0);
        self.game_surface = Some(id);
        self.game_visible = true;
        Ok(())
    }
    /// The Game view's canvas was resized.
    pub fn resize_game(&mut self, width: u32, height: u32) {
        if let Some(id) = self.game_surface {
            self.gfx.use_surface(id);
            self.gfx.resize(width.max(1), height.max(1));
            self.gfx.use_surface(0);
        }
    }
    /// Which views are on screen (hidden dock tabs aren't drawn).
    pub fn set_views(&mut self, scene: bool, game: bool) {
        self.scene_visible = scene;
        self.game_visible = game;
    }

    pub fn open_scene(&mut self, key: &str) -> Result<(), JsValue> {
        self.core.open_scene(&mut self.gfx, key).map_err(|e| JsValue::from_str(&e))
    }
    pub fn scene(&self) -> Option<String> {
        self.core.scene.clone()
    }
    pub fn save_scene(&mut self) -> Result<String, JsValue> {
        self.core.save_scene().map_err(|e| JsValue::from_str(&e))
    }
    /// JSON array of `{ id, name, parent, kind }`.
    pub fn hierarchy(&self) -> String {
        serde_json::to_string(&self.core.hierarchy()).unwrap_or_default()
    }

    pub fn select(&mut self, id: Option<String>) {
        self.core.select(id.as_deref().and_then(entity_of));
    }
    /// Selects several entities (JSON array of ids; the last is active).
    pub fn select_many(&mut self, ids_json: &str) {
        let ids: Vec<String> = serde_json::from_str(ids_json).unwrap_or_default();
        self.core.select_many(ids.iter().filter_map(|i| entity_of(i)).collect());
    }
    /// JSON array of the selected ids (active last).
    pub fn selection(&self) -> String {
        serde_json::to_string(&self.core.selection.iter().map(|e| id_of(*e)).collect::<Vec<_>>()).unwrap_or_default()
    }

    // ------------------------------------------------------------ undo / clipboard
    /// Call before changing the scene (Undo goes back to this state).
    pub fn record_undo(&mut self, label: &str) {
        self.core.record_undo(label);
    }
    pub fn undo(&mut self) -> Option<String> {
        self.core.undo(&mut self.gfx)
    }
    pub fn redo(&mut self) -> Option<String> {
        self.core.redo(&mut self.gfx)
    }
    pub fn undo_label(&self) -> Option<String> {
        self.core.undo_label().map(str::to_string)
    }
    pub fn redo_label(&self) -> Option<String> {
        self.core.redo_label().map(str::to_string)
    }
    /// The selection as scene JSON (clipboard), or nothing.
    pub fn copy_selection(&mut self) -> Option<String> {
        self.core.copy_selection()
    }
    /// Pastes clipboard JSON under `parent`; returns the new ids (JSON array).
    pub fn paste(&mut self, json: &str, parent: Option<String>) -> Result<String, JsValue> {
        let ids = self.core.paste(&mut self.gfx, json, parent.as_deref().and_then(entity_of)).map_err(|e| JsValue::from_str(&e))?;
        Ok(serde_json::to_string(&ids.into_iter().map(id_of).collect::<Vec<_>>()).unwrap_or_default())
    }
    /// Duplicates the selection; returns the new ids (JSON array).
    pub fn duplicate(&mut self) -> Result<String, JsValue> {
        let ids = self.core.duplicate_selection(&mut self.gfx).map_err(|e| JsValue::from_str(&e))?;
        Ok(serde_json::to_string(&ids.into_iter().map(id_of).collect::<Vec<_>>()).unwrap_or_default())
    }
    /// Runs an Inspector button of a component (e.g. NavMeshSurface ▸ Bake); returns its message.
    pub fn component_action(&mut self, id: &str, component: &str, action: &str) -> Result<String, JsValue> {
        let e = entity_of(id).ok_or_else(|| JsValue::from_str("no entity"))?;
        self.core.component_action(&mut self.gfx, e, component, action).map_err(|e| JsValue::from_str(&e))
    }
    /// `{ components: { name: { menu, defaults?, fields?, requires? } }, behaviours: [...] }`.
    pub fn component_info(&self) -> String {
        self.core.component_info().to_string()
    }
    pub fn selected(&self) -> Option<String> {
        self.core.selected.map(id_of)
    }
    /// Picks at (x, y) in 0..1 of the view; selects and returns the entity id.
    pub fn pick(&mut self, x: f32, y: f32) -> Option<String> {
        let e = self.core.pick(&self.gfx, x, y);
        self.core.select(e);
        e.map(id_of)
    }
    /// `{ position, euler, scale }` of an entity.
    pub fn transform(&self, id: &str) -> Option<String> {
        entity_of(id).and_then(|e| self.core.transform(e)).and_then(|t| serde_json::to_string(&t).ok())
    }
    pub fn set_transform(&mut self, id: &str, json: &str) -> Result<(), JsValue> {
        let t: TransformEdit = serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
        if let Some(e) = entity_of(id) {
            self.core.set_transform(e, &t);
        }
        Ok(())
    }
    /// Unity's SetActive (the object and its children).
    pub fn set_active(&mut self, id: &str, on: bool) {
        if let Some(e) = entity_of(id) {
            goat_runtime::set_active(&mut self.core.active_mut().world, e, on);
        }
    }
    /// Sets the tag ("Untagged" / empty removes it).
    pub fn set_tag(&mut self, id: &str, tag: &str) {
        if let Some(e) = entity_of(id) {
            if tag.is_empty() || tag == "Untagged" {
                let _ = self.core.active_mut().world.remove_one::<goat_runtime::Tag>(e);
            } else {
                let _ = self.core.active_mut().world.insert_one(e, goat_runtime::Tag(tag.to_string()));
            }
        }
    }
    pub fn rename(&mut self, id: &str, name: &str) {
        if let Some(e) = entity_of(id) {
            self.core.rename(e, name);
        }
    }

    // ------------------------------------------------------------ components / entities
    /// JSON array of the registered component names.
    pub fn component_names(&self) -> String {
        serde_json::to_string(&self.core.component_names()).unwrap_or_default()
    }
    /// JSON `[{ name, value }]` of an entity's components.
    pub fn components(&mut self, id: &str) -> String {
        entity_of(id).map(|e| self.core.components(e).to_string()).unwrap_or_else(|| "[]".into())
    }
    pub fn set_component(&mut self, id: &str, name: &str, json: &str) -> Result<(), JsValue> {
        let e = entity_of(id).ok_or_else(|| JsValue::from_str("no entity"))?;
        let v: serde_json::Value = serde_json::from_str(json).map_err(|e| JsValue::from_str(&e.to_string()))?;
        self.core.set_component(&mut self.gfx, e, name, &v).map_err(|e| JsValue::from_str(&e))
    }
    pub fn remove_component(&mut self, id: &str, name: &str) {
        if let Some(e) = entity_of(id) {
            self.core.remove_component(e, name);
        }
    }
    pub fn create_entity(&mut self, name: &str, parent: Option<String>) -> String {
        id_of(self.core.create_entity(name, parent.as_deref().and_then(entity_of)))
    }
    pub fn delete_entity(&mut self, id: &str) {
        if let Some(e) = entity_of(id) {
            self.core.delete_entity(e);
        }
    }
    pub fn set_parent(&mut self, id: &str, parent: Option<String>) {
        if let Some(e) = entity_of(id) {
            self.core.set_parent(e, parent.as_deref().and_then(entity_of));
        }
    }
    /// Drops a model / prefab at a view point (0..1); returns the new entity.
    pub fn instantiate(&mut self, key: &str, x: f32, y: f32) -> Result<String, JsValue> {
        let at = self.core.ground_point(x, y);
        self.core.instantiate(&mut self.gfx, key, at).map(id_of).map_err(|e| JsValue::from_str(&e))
    }

    // ------------------------------------------------------------ Animation window
    /// `[{ id, name, path }]` of an animated root and the objects under it.
    pub fn anim_paths(&self, root: &str) -> String {
        entity_of(root).map(|e| self.core.anim_paths(e).to_string()).unwrap_or_else(|| "[]".into())
    }
    /// Shows a clip (its JSON) at a time on the root's objects; `anim_preview_end` puts them back.
    pub fn anim_preview(&mut self, root: &str, clip_json: &str, time: f32) -> Result<(), JsValue> {
        let e = entity_of(root).ok_or_else(|| JsValue::from_str("no entity"))?;
        self.core.anim_preview(&mut self.gfx, e, clip_json, time).map_err(|e| JsValue::from_str(&e))
    }
    pub fn anim_preview_end(&mut self) {
        self.core.anim_preview_end(&mut self.gfx);
    }

    // ------------------------------------------------------------ shaders
    /// `{ name, kind, properties, state, … }` or `{ errors }` of a `.shader` file.
    pub fn shader_info(&self, key: &str) -> String {
        self.core.shader_info(key).to_string()
    }

    // ------------------------------------------------------------ scripts
    /// `{ kind: "behaviour" | "scriptableObject", fields: {...} }` or `{ error }` of a script.
    pub fn script_info(&mut self, src: &str) -> String {
        self.core.script_info(&mut self.gfx, src).to_string()
    }

    // ------------------------------------------------------------ gizmos
    /// "move" / "rotate" / "scale" / "transform".
    pub fn set_gizmo_mode(&mut self, mode: &str) {
        self.core.tools.mode = match mode {
            "rotate" => GizmoMode::Rotate,
            "scale" => GizmoMode::Scale,
            "transform" => GizmoMode::Transform,
            _ => GizmoMode::Move,
        };
    }
    /// Starts a gizmo drag if (x, y) (0..1 of a w × h view) is on a handle.
    pub fn gizmo_begin(&mut self, x: f32, y: f32, w: f32, h: f32) -> bool {
        match self.core.gizmo_hit(x, y, w, h) {
            Some(handle) => {
                self.core.gizmo_start(handle, goat_core::math::Vec2::new(x * w, y * h));
                true
            }
            None => false,
        }
    }
    /// Pointer over the Scene view without a button: highlights the handle under it.
    pub fn gizmo_hover(&mut self, x: f32, y: f32, w: f32, h: f32) {
        self.core.gizmo_hover(x, y, w, h);
    }
    /// JSON shapes the UI draws over the Scene view (handles, selection outlines, icons), in
    /// pixels of a `w × h` view; `px, py` = pointer (pixels, negative = none).
    pub fn scene_overlay(&mut self, w: f32, h: f32, px: f32, py: f32) -> String {
        let pointer = (px >= 0.0).then(|| goat_core::math::Vec2::new(px, py));
        self.core.scene_overlay(&self.gfx, w, h, pointer).to_string()
    }
    /// snap = Ctrl held (increment snapping).
    pub fn gizmo_drag(&mut self, dx: f32, dy: f32, w: f32, h: f32, snap: bool) {
        self.core.gizmo_drag(dx, dy, w, h, snap);
    }
    pub fn gizmo_end(&mut self) {
        self.core.gizmo_stop();
    }
    /// Tool handle settings: Local / Global axes, Center / Pivot, snap increments.
    pub fn set_tool_handles(&mut self, local: bool, center: bool, snap_move: f32, snap_rotate: f32, snap_scale: f32) {
        let t = &mut self.core.tools;
        t.local = local;
        t.center = center;
        t.snap = [snap_move, snap_rotate, snap_scale];
    }

    // ------------------------------------------------------------ prefabs
    /// `{ root, key, overrides: [...] }` of the prefab instance an entity belongs to, or "null".
    pub fn prefab_info(&mut self, id: &str) -> String {
        entity_of(id).map(|e| self.core.prefab_info(e).to_string()).unwrap_or_else(|| "null".into())
    }
    /// Revert All: returns the new root id.
    pub fn revert_prefab(&mut self, id: &str) -> Result<String, JsValue> {
        let e = entity_of(id).ok_or_else(|| JsValue::from_str("no such entity"))?;
        self.core.revert_prefab(&mut self.gfx, e).map(id_of).map_err(|e| JsValue::from_str(&e))
    }
    /// Apply All: returns `{ key, text }` (the prefab file to write).
    pub fn apply_prefab(&mut self, id: &str) -> Result<String, JsValue> {
        let e = entity_of(id).ok_or_else(|| JsValue::from_str("no such entity"))?;
        self.core.apply_prefab(&mut self.gfx, e).map(|v| v.to_string()).map_err(|e| JsValue::from_str(&e))
    }

    // ------------------------------------------------------------ Scene view options
    /// Unity's 2D button (orthographic view down −Z, pan / zoom only).
    pub fn set_2d(&mut self, on: bool) {
        self.core.set_2d(on);
    }
    /// Persp / Iso.
    pub fn set_ortho(&mut self, on: bool) {
        self.core.set_ortho(on);
    }
    /// View gizmo click: "x" / "-x" / "y" / "-y" / "z" / "-z".
    pub fn view_axis(&mut self, axis: &str) {
        self.core.view_axis(axis);
    }
    /// { rotation: [x, y, z, w], distance, view: { mode2d, ortho, grid, gizmos, scene_view } }
    pub fn view_state(&self) -> String {
        self.core.view_state().to_string()
    }
    pub fn set_grid(&mut self, on: bool) {
        self.core.view.grid = on;
    }
    pub fn set_gizmos(&mut self, on: bool) {
        self.core.view.gizmos = on;
    }
    /// The canvas shows the Scene view (true) or the Game view (false).
    pub fn set_scene_view(&mut self, on: bool) {
        self.core.view.scene_view = on;
    }
    pub fn orbit(&mut self, dx: f32, dy: f32) {
        self.core.orbit_by(dx, dy);
    }
    pub fn pan(&mut self, dx: f32, dy: f32) {
        self.core.pan_by(dx, dy);
    }
    pub fn zoom(&mut self, delta: f32) {
        self.core.zoom_by(delta);
    }
    pub fn frame_selected(&mut self) {
        self.core.frame_selected(&self.gfx);
    }

    /// Play mode; `dual_3ds` shows the game as the 3DS's two screens.
    pub fn play(&mut self, dual_3ds: bool) {
        self.dual = dual_3ds;
        self.core.play();
    }
    pub fn stop(&mut self) {
        self.core.stop();
    }
    /// The Game view's 3DS two-screen layout (also in edit mode); the Scene view is always one view.
    pub fn set_dual_3ds(&mut self, on: bool) {
        self.dual = on;
    }
    /// Pauses / resumes Play mode (the Game view keeps drawing).
    pub fn set_paused(&mut self, paused: bool) {
        self.core.paused = paused;
    }
    /// Console expression in the running game: its id (0 = not playing); answers come from
    /// `console_results`.
    pub fn console_eval(&mut self, code: &str) -> u32 {
        self.core.console_eval(code).unwrap_or(0)
    }
    /// `[{ id, text, ok }]` answered since the last call.
    pub fn console_results(&mut self) -> String {
        self.core.console_results().to_string()
    }
    /// The Console's Error Pause: pause when a script fails.
    pub fn set_error_pause(&mut self, on: bool) {
        self.core.debug.error_pause = on;
    }
    /// Why the game paused itself since the last call (Debug.break / Error Pause), "" = it didn't.
    pub fn take_pause_reason(&mut self) -> String {
        self.core.take_pause_reason()
    }
    pub fn is_paused(&self) -> bool {
        self.core.paused
    }
    /// One frame while paused (Unity's Step).
    pub fn step(&mut self) {
        self.core.step_once = true;
    }
    /// The profiler as JSON: `{ sections: [[name, ms]], draw_calls, triangles, history: [{ s, d, t }] }`.
    pub fn profiler(&mut self) -> String {
        self.core.profiler_json().to_string()
    }
    pub fn is_playing(&self) -> bool {
        self.core.is_playing()
    }
    pub fn key(&mut self, code: &str, down: bool) {
        self.core.key(code, down);
    }

    /// One frame (`dt` seconds).
    pub fn frame(&mut self, dt: f32) {
        let dt = dt.min(0.1);
        let Some(game) = self.game_surface else {
            // one canvas: the 3DS screens only in the Game view
            let layout = if self.dual && !self.core.view.scene_view { DisplayLayout::Dual3ds } else { DisplayLayout::Window };
            if self.gfx.layout() != layout {
                self.gfx.set_layout(layout);
            }
            self.core.frame(&mut self.gfx, dt);
            return;
        };
        // two canvases: the frame runs once (the game while playing, the edit world's tick
        // otherwise) in the pass that is on screen, the other view only draws
        let playing = self.core.is_playing();
        let (scene, game_on) = (self.scene_visible, self.game_visible);
        let game_simulates = if playing { game_on || !scene } else { !scene };
        if game_on || game_simulates {
            self.gfx.use_surface(game);
            let layout = if self.dual { DisplayLayout::Dual3ds } else { DisplayLayout::Window };
            if self.gfx.layout() != layout {
                self.gfx.set_layout(layout);
            }
            self.core.frame_pass(&mut self.gfx, dt, ViewPass::Game, game_simulates);
        }
        if scene || !game_simulates {
            self.gfx.use_surface(0);
            if self.gfx.layout() != DisplayLayout::Window {
                self.gfx.set_layout(DisplayLayout::Window);
            }
            self.core.frame_pass(&mut self.gfx, dt, ViewPass::Scene, !game_simulates);
        }
        self.gfx.use_surface(0);
    }

    /// Draw calls / triangles of the last frame.
    pub fn stats(&self) -> String {
        let s = if let Some(p) = &self.core.play { p.last_stats } else { self.core.edit.last_stats };
        format!("{} draws · {} tris", s.draw_calls, s.triangles)
    }
}
